// Des: Unit tests for plus pick helper
// Flo: fixed seed > pick from list > assert range
// I/O: plus JSON values > pass or fail
// ===================================================================
const std = @import("std"); const stor = @import("taskstore"); const time = @import("tasktime"); const armz = @import("taskarm"); const supe = @import("tasksuper"); const tick = @import("tk-task-tick.zig");
const tszz = std.testing; const Sche = tick.Sche; const CF = tick.CF;
fn plusJson(allo: std.mem.Allocator, json: []const u8) std.json.Value { return std.json.parseFromSliceLeaky(std.json.Value, allo, json, .{}) catch unreachable; }
test "plusPick: a list picks one value (repeats weigh more), a letter = default (0, secs 0..59)" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); var prng = std.Random.DefaultPrng.init(42); const rngz = prng.random(); const plus_exac = plusJson(allo, "[[1],[2],[3],[4],[5],[6]]"); try tszz.expectEqual(@as(i64, 365 * 86_400_000 + 2 * 30 * 86_400_000 + 3 * 86_400_000 + 4 * 3_600_000 + 5 * 60_000 + 6_000), Sche.plusPick(rngz, plus_exac)); const plus_mins = plusJson(allo, "[\"y\",\"m\",\"d\",\"h\",[1,2,3],\"s\"]"); var seen_lowz = false; var seen_higz = false; for (0..300) |_| { const valu = Sche.plusPick(rngz, plus_mins); const minu = @divFloor(valu, 60_000); try tszz.expect(minu >= 1 and minu <= 3); try tszz.expect(@mod(valu, 60_000) < 60_000); if (minu == 1) seen_lowz = true; if (minu == 3) seen_higz = true; } try tszz.expect(seen_lowz and seen_higz); const plus_secs = plusJson(allo, "[\"y\",\"m\",\"d\",\"h\",\"n\",[7]]"); try tszz.expectEqual(@as(i64, 7_000), Sche.plusPick(rngz, plus_secs)); const plus_weig = plusJson(allo, "[\"y\",\"m\",\"d\",\"h\",\"n\",[0,0,0,1]]"); var onez: u32 = 0; for (0..400) |_| onez += @intCast(@divFloor(Sche.plusPick(rngz, plus_weig), 1000)); try tszz.expect(onez > 40 and onez < 200); const plus_rngp = plusJson(allo, "[\"y\",\"m\",\"d\",\"h\",\"4..12\",\"s\"]"); const plus_rngl = plusJson(allo, "[\"y\",\"m\",\"d\",\"h\",[1,\"5..7\"],\"s\"]"); var seen_four = false; var seen_twel = false; for (0..400) |_| { const minu = @divFloor(Sche.plusPick(rngz, plus_rngp), 60_000); try tszz.expect(minu >= 4 and minu <= 12); if (minu == 4) seen_four = true; if (minu == 12) seen_twel = true; const list = @divFloor(Sche.plusPick(rngz, plus_rngl), 60_000); try tszz.expect(list == 1 or (list >= 5 and list <= 7)); } try tszz.expect(seen_four and seen_twel); for (0..100) |_| try tszz.expect(Sche.plusPick(rngz, null) < 60_000); for (0..100) |_| try tszz.expect(Sche.plusPick(rngz, plusJson(allo, "[]")) < 60_000); for (0..100) |_| { const valu = Sche.plusPick(rngz, plusJson(allo, "[\"y\",\"m\",\"d\",\"h\",[2]]")); try tszz.expect(valu >= 120_000 and valu < 180_000); } }
